WITH filtered AS (SELECT *, CONCAT(brand, ', ', product_name) AS brand_product_name, COALESCE(brand, 'OTHER') AS brand_filled FROM products WHERE launch_date >= TO_DATE('2023-04-19')), metrics AS (SELECT id, product_name, category, stock_qty, supplier_id, brand_filled, CORR(cost, price) OVER (PARTITION BY supplier_id) AS corr_cost_price, MIN(stock_qty) OVER (PARTITION BY category) AS category_min_stock_qty, AVG(price) OVER (PARTITION BY supplier_id ORDER BY cost ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS price_avg_6 FROM filtered), joined AS (SELECT s.*, p2.city FROM metrics s JOIN suppliers p2 ON s.supplier_id = p2.id), filtered_products AS (SELECT id, product_name, category, supplier_id, corr_cost_price, category_min_stock_qty, price_avg_6, TRIM(product_name) AS clean_product_name, COALESCE(city, 'OTHER') AS resolved_city FROM joined WHERE city IS NOT NULL AND product_name LIKE '%Bott%'), latest AS (SELECT id, product_name, category, supplier_id, category_min_stock_qty, price_avg_6, clean_product_name, resolved_city FROM filtered_products QUALIFY ROW_NUMBER() OVER (PARTITION BY supplier_id, category ORDER BY category_min_stock_qty ASC, id ASC) = 1) SELECT id, product_name, category, price_avg_6, clean_product_name FROM latest ORDER BY id DESC NULLS LAST
